pub fn common_prefix(words: List[Str]) -> Str {
  if words.is_empty() {
    return ""
  }
  let first = words.get_or(0, "")
  var out = ""
  for c in first.chars() {
    let p = out + c
    if words.all(fn(w: Str) => w.starts_with(p)) {
      out = p
    } else {
      return out
    }
  }
  return out
}
